UPDATE pit_stops SET is_fast_pit_stop = CASE 
    WHEN durtxt ~ '^\d+\.\d+$' THEN CAST(durtxt AS numeric) < 2500
    WHEN durtxt ~ '^\d+:\d+\.\d+$' THEN (CAST(SPLIT_PART(durtxt, ':', 1) AS numeric) * 60 + CAST(SPLIT_PART(SPLIT_PART(durtxt, ':', 2), '.', 1) AS numeric) + CAST('0.' || SPLIT_PART(SPLIT_PART(durtxt, ':', 2), '.', 2) AS numeric)) * 1000 < 2500
